using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: reversed nibble values (index 0..15 → bit-reversed nibble shifted left 4)
    private static ReadOnlySpan<byte> NibbleHiLut => [
        0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
        0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0
    ];

    // Lookup table: reversed nibble values (index 0..15 → bit-reversed nibble)
    private static ReadOnlySpan<byte> NibbleLoLut => [
        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    ];

    // Full 256-byte scalar lookup table
    private static readonly byte[] ScalarLut = BuildScalarLut();

    private static byte[] BuildScalarLut()
    {
        var lut = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            lut[i] = (byte)((NibbleHiLut[i & 0x0F]) | (NibbleLoLut[i >> 4]));
        }
        return lut;
    }

    public static void ReverseInPlace(Span<byte> data)
    {
        if (Avx2.IsSupported)
        {
            ReverseAvx2(data);
        }
        else if (Ssse3.IsSupported)
        {
            ReverseSsse3(data);
        }
        else if (AdvSimd.IsSupported)
        {
            ReverseNeon(data);
        }
        else
        {
            ReverseScalar(data);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseAvx2(Span<byte> data)
    {
        var loLut = Vector256.Create(NibbleLoLut);
        var hiLut = Vector256.Create(NibbleHiLut);
        var mask = Vector256.Create((byte)0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector256<byte>.Count;

        while (i <= lastBlockStart)
        {
            var vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);
            var lo = vec & mask;
            var hi = Avx2.ShiftRightLogical(vec.AsInt16(), 4).AsByte() & mask;
            var result = Avx2.Shuffle(hiLut, lo) | Avx2.Shuffle(loLut, hi);
            result.StoreUnsafe(ref ptr, (nuint)i);
            i += Vector256<byte>.Count;
        }

        // Scalar tail
        byte[] lut = ScalarLut;
        for (; i < data.Length; i++)
        {
            Unsafe.Add(ref ptr, i) = lut[Unsafe.Add(ref ptr, i)];
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseSsse3(Span<byte> data)
    {
        var loLut = Vector128.Create(NibbleLoLut);
        var hiLut = Vector128.Create(NibbleHiLut);
        var mask = Vector128.Create((byte)0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector128<byte>.Count;

        while (i <= lastBlockStart)
        {
            var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            var lo = vec & mask;
            var hi = Sse2.ShiftRightLogical(vec.AsInt16(), 4).AsByte() & mask;
            var result = Ssse3.Shuffle(hiLut, lo) | Ssse3.Shuffle(loLut, hi);
            result.StoreUnsafe(ref ptr, (nuint)i);
            i += Vector128<byte>.Count;
        }

        byte[] lut = ScalarLut;
        for (; i < data.Length; i++)
        {
            Unsafe.Add(ref ptr, i) = lut[Unsafe.Add(ref ptr, i)];
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseNeon(Span<byte> data)
    {
        var loLut = Vector128.Create(NibbleLoLut);
        var hiLut = Vector128.Create(NibbleHiLut);
        var mask = Vector128.Create((byte)0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector128<byte>.Count;

        while (i <= lastBlockStart)
        {
            var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            var lo = vec & mask;
            var hi = AdvSimd.ShiftRightLogical(vec, 4) & mask;
            var result = AdvSimd.Arm64.VectorTableLookup(hiLut, lo) |
                         AdvSimd.Arm64.VectorTableLookup(loLut, hi);
            result.StoreUnsafe(ref ptr, (nuint)i);
            i += Vector128<byte>.Count;
        }

        byte[] lut = ScalarLut;
        for (; i < data.Length; i++)
        {
            Unsafe.Add(ref ptr, i) = lut[Unsafe.Add(ref ptr, i)];
        }
    }

    private static void ReverseScalar(Span<byte> data)
    {
        byte[] lut = ScalarLut;
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        for (int i = 0; i < data.Length; i++)
        {
            Unsafe.Add(ref ptr, i) = lut[Unsafe.Add(ref ptr, i)];
        }
    }
}

